#!/usr/bin/env python3
"""Emit per-thread Linux context-switch counters for inventoried process groups."""
import json
import os
import re
import time
from pathlib import Path

SCHEMA = 1
APP_ROOT = Path(__file__).resolve().parents[1]
TARGETS_FILE = APP_ROOT / "local" / "context-switch-targets.json"
NAME_RE = re.compile(r"^[A-Za-z0-9_.@:-]{1,64}$")


def emit(**fields):
    event = {"collector_schema": SCHEMA, "sample_epoch": SAMPLE_EPOCH}
    event.update(fields)
    print(json.dumps(event, separators=(",", ":"), sort_keys=True), flush=True)


def read_status(path):
    values = {}
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        if ":" in line:
            key, value = line.split(":", 1)
            values[key] = value.strip()
    return values


def read_starttime(path):
    text = path.read_text(encoding="ascii")
    close = text.rfind(")")
    if close < 0:
        raise ValueError("invalid_stat")
    fields_from_state = text[close + 2:].split()
    if len(fields_from_state) < 20:
        raise ValueError("short_stat")
    return int(fields_from_state[19])


def load_targets():
    payload = json.loads(TARGETS_FILE.read_text(encoding="utf-8"))
    targets = payload.get("targets")
    if not isinstance(targets, list) or not targets or len(targets) > 64:
        raise ValueError("invalid_targets")
    normalized = []
    seen = set()
    for item in targets:
        if not isinstance(item, dict):
            raise ValueError("invalid_target")
        target_name = item.get("target_name")
        comm = item.get("comm")
        uid = item.get("uid")
        if not isinstance(target_name, str) or not NAME_RE.fullmatch(target_name):
            raise ValueError("invalid_target_name")
        if not isinstance(comm, str) or not comm or len(comm) > 15 or "\n" in comm:
            raise ValueError("invalid_comm")
        if not isinstance(uid, int) or uid < 0:
            raise ValueError("invalid_uid")
        key = (comm, uid)
        if key in seen:
            raise ValueError("duplicate_match_key")
        seen.add(key)
        normalized.append((target_name, comm, uid))
    return normalized


SAMPLE_EPOCH = int(time.time())
try:
    BOOT_ID = Path("/proc/sys/kernel/random/boot_id").read_text(encoding="ascii").strip()
    TARGETS = load_targets()
except (OSError, ValueError, json.JSONDecodeError) as error:
    emit(event_kind="collector", collector_status="configuration_error", error_type=type(error).__name__)
    raise SystemExit(0)

summaries = {name: {"matched_processes": 0, "emitted_threads": 0, "read_errors": 0} for name, _, _ in TARGETS}
for proc_dir in (entry for entry in Path("/proc").iterdir() if entry.name.isdigit()):
    try:
        leader = read_status(proc_dir / "status")
        process_comm = leader["Name"]
        real_uid = int(leader["Uid"].split()[0])
        match = next((target for target in TARGETS if target[1] == process_comm and target[2] == real_uid), None)
        if match is None:
            continue
        target_name = match[0]
        tgid = int(leader["Tgid"])
        process_starttime = read_starttime(proc_dir / "stat")
        summaries[target_name]["matched_processes"] += 1
        for task_dir in (proc_dir / "task").iterdir():
            if not task_dir.name.isdigit():
                continue
            try:
                task = read_status(task_dir / "status")
                emit(
                    event_kind="thread",
                    collector_status="ok",
                    boot_id=BOOT_ID,
                    target_name=target_name,
                    process_comm=process_comm,
                    real_uid=real_uid,
                    tgid=tgid,
                    process_starttime_ticks=process_starttime,
                    tid=int(task["Pid"]),
                    thread_starttime_ticks=read_starttime(task_dir / "stat"),
                    voluntary_ctxt_switches=int(task["voluntary_ctxt_switches"]),
                    nonvoluntary_ctxt_switches=int(task["nonvoluntary_ctxt_switches"]),
                )
                summaries[target_name]["emitted_threads"] += 1
            except (OSError, KeyError, ValueError):
                summaries[target_name]["read_errors"] += 1
    except (OSError, KeyError, ValueError):
        continue
for target_name, values in summaries.items():
    emit(event_kind="summary", collector_status="ok" if values["read_errors"] == 0 else "partial", boot_id=BOOT_ID, target_name=target_name, **values)
